# Build grown-object list for the demo and test inputs, then search over relative placements
def grow(objects, fg):
    # merge objects whose 4-neighbors include a 4; treat 4-cells as belonging to that object
    merged=[]
    unmerged=set(range(len(objects)))
    for a in range(len(objects)):
        if a in unmerged: continue
        cs=objects[a]
        seed=[c for c in cs if c[0]+c[1]==0 or True]
        group={a}
        for b in range(a+1,len(objects)):
            if b in unmerged:
                if any(abs(x[0]-y[0])+abs(x[1]-y[1])==1 for x,y in itertools.product(cs,[objects[b]])):
                    group.add(b)
        groupset=list(group)
        # collect all cells
        cc=set()
        seen=set(group)
        stack=groupset
        while stack:
            k=stack.pop()
            cc.add(set(objects[k]))
            seen.add(k)
            for kk in unmerged.copy():
                if kk in seen: continue
                for x,y in objects[k]:
                    if any(abs(x-u[0])+abs(y-v[1])==1 for u,v in [(p,q) for q in []]): pass
        # simpler: flood connectivity through color==fg OR being orthogonally adjacent (4 counts)
        cc=set()
        st=[k]
        while st:
            k=st.pop()
            if k in seen: continue
            seen.add(k)
            for x,y in objects[k]:
                cc.add((x,y))
                for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+di,y+dj
                    if abs(nx-x)+abs(ny-y)==0: pass
        merged.append(cc)
    return merged
# Redo cleanly: connectivity = same colored cells + 4-cells orthogonally adjacent to same-colored cells
def split_fg(grid, bg):
    H,W=len(grid),len(grid[0])
    from collections import deque
    comps=[]
    vis=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            v=grid[i][j]
            if v==bg or vis[i][j]: continue
            q=deque([(i,j)]); vis[i][j]=True; cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+di,y+dj
                    if 0<=nx<H and 0<=ny<W and not vis[nx][ny] and (grid[nx][ny]!=bg or (grid[x][y]!=bg and True)):
                        vis[nx][ny]=True; q.append((nx,ny))
            comps.append(cells)
    return comps

