def translate_pattern(cells,O,val):
    # output cells colored val
    oc=[(x,y) for x,row in enumerate(O) for y,v in enumerate(row) if v==val]
    cs=set(cells)
    best=None
    for dx in range(-len(O)+min(x for x,_ in oc), len(O)-min(x for x,_ in oc)):
        for dy in range(-len(O[0])+min(y for _,y in oc), len(O[0])-min(y for _,y in oc)):
            sh={(x+dx,y+dy) for x,y in cells}
            inter=len(sh & set(oc))
            if best is None or inter>best[0]: best=(inter,dx,dy,sh&set(oc))
    return best
